  position: absolute;
  right: 8px;
  top: 6px;
  bottom: 6px;
  width: 4px;
  background: repeating-linear-gradient(
    to bottom,
    #d61f1f 0,
    #d61f1f 6px,
    #ffffff 6px,
    #ffffff 12px
  );
}

.lane-label {
  font-weight: 600;
}

.bug-runway {
  position: relative;
  height: 48px;
  overflow: hidden;
}

.bug-runner {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translate(0, -50%);
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-weight: 600;
  user-select: none;
}

.bug-runner .icon {
  font-size: 1.6rem;
}

.bug-name {
  font-size: 0.86rem;
  color: #2e3a4f;
}

@media (max-width: 980px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

export const ICON_OPTIONS = [
  { id: "ladybug", symbol: "🐞", label: "Ladybug" },
  { id: "beetle", symbol: "🪲", label: "Beetle" },
  { id: "ant", symbol: "🐜", label: "Ant" }
];

export const SPEED_RANGES = {
  slow: [1.2, 2.0],
  normal: [2.1, 3.2],
  fast: [3.3, 4.8]
};

const createLane = (laneId, iconId) => ({
  laneId,
  selectedIconId: iconId,
  bugName: `Bug ${laneId}`,
  predictedWinner: false,
  positionPx: 0,
  currentVelocityPxPerFrame: 0
});

const initialState = {
  lanes: [
    createLane(1, "ladybug"),
    createLane(2, "beetle"),
    createLane(3, "ant"),
    createLane(4, "ladybug")
  ],
  settings: {
    speedTier: "normal",
    trackLengthPx: 0
  },
  race: {
    status: "idle",
    winnerLaneId: null,
    raceId: 0
  },
  metrics: {
    sessionRacesRun: 0
  },
  ui: {
    warning: "",
    error: "",
    result: ""
  }
};

export const state = structuredClone(initialState);

export function getLaneById(laneId) {
  return state.lanes.find((lane) => lane.laneId === laneId);
}

export function setLaneIcon(laneId, iconId) {
  const lane = getLaneById(laneId);
  if (lane) {
    lane.selectedIconId = iconId;
  }
}

export function setLaneName(laneId, bugName) {
  const lane = getLaneById(laneId);
  if (lane) {
    lane.bugName = bugName;
  }
}

export function setPredictedWinner(laneId) {
  for (const lane of state.lanes) {
    lane.predictedWinner = lane.laneId === laneId;
  }
}

export function getPredictedWinnerLaneId() {
  const lane = state.lanes.find((entry) => entry.predictedWinner);
  return lane ? lane.laneId : null;
}

export function setSpeedTier(speedTier) {
  state.settings.speedTier = speedTier;
}

export function setTrackLength(trackLengthPx) {
  state.settings.trackLengthPx = trackLengthPx;
}

export function setRaceStatus(status) {
  state.race.status = status;
}

export function beginRace() {
  state.race.raceId += 1;
  state.race.status = "racing";
  state.race.winnerLaneId = null;
  state.ui.error = "";
  state.ui.result = "";
}

export function finishRace(winnerLaneId) {
  state.race.status = "finished";
  state.race.winnerLaneId = winnerLaneId;
}

export function resetLanePositions() {
  for (const lane of state.lanes) {
    lane.positionPx = 0;
    lane.currentVelocityPxPerFrame = 0;
  }
}

export function setLanePosition(laneId, positionPx) {
  const lane = getLaneById(laneId);
  if (lane) {
    lane.positionPx = positionPx;
  }
}

export function setLaneVelocity(laneId, velocityPxPerFrame) {
  const lane = getLaneById(laneId);
  if (lane) {
    lane.currentVelocityPxPerFrame = velocityPxPerFrame;
  }
}

export function setWarning(message) {
  state.ui.warning = message;
}

export function setError(message) {
  state.ui.error = message;
}

export function setResult(message) {
  state.ui.result = message;
}

export function incrementSessionRaceCount() {
  state.metrics.sessionRacesRun += 1;
}

export function markReadyState() {
  state.race.status = "ready";
}

function normalizeName(name) {
  return name.trim().toLowerCase();
}

export function hasDuplicateIcons(lanes) {
  const seen = new Set();
  for (const lane of lanes) {
    if (seen.has(lane.selectedIconId)) {
      return true;
    }
    seen.add(lane.selectedIconId);
  }
  return false;
}

export function hasDuplicateNames(lanes) {
  const seen = new Set();
  for (const lane of lanes) {
    const normalized = normalizeName(lane.bugName);
    if (!normalized) {
      continue;
    }
    if (seen.has(normalized)) {
      return true;
    }
    seen.add(normalized);
  }
  return false;
}

export function hasWinnerSelection(lanes) {
  return lanes.some((lane) => lane.predictedWinner);
}

export function validateBeforeStart(lanes) {
  if (hasDuplicateNames(lanes)) {
    return {
      valid: false,
      error: "Bug names must be unique across all lanes.",
      warning: hasDuplicateIcons(lanes)
        ? "Warning: duplicate bug icons are selected across lanes."
        : ""
    };
  }

  if (!hasWinnerSelection(lanes)) {
    return {
      valid: false,
      error: "Select a predicted winner before starting the race.",
      warning: hasDuplicateIcons(lanes)
        ? "Warning: duplicate bug icons are selected across lanes."
        : ""
    };
  }

  return {
    valid: true,
    error: "",
    warning: hasDuplicateIcons(lanes)
      ? "Warning: duplicate bug icons are selected across lanes."
      : ""
  };
}

import { SPEED_RANGES } from "./state.js";

const FRAME_RATE = 60;

const perFrameToPerMs = (pxPerFrame) => (pxPerFrame * FRAME_RATE) / 1000;

export function assignLaneVelocities(lanes, speedTier) {
  const [minSpeed, maxSpeed] = SPEED_RANGES[speedTier] ?? SPEED_RANGES.normal;

  return lanes.map((lane) => {
    const sampledSpeed = minSpeed + Math.random() * (maxSpeed - minSpeed);
    return {
      laneId: lane.laneId,
      velocityPxPerFrame: sampledSpeed,
      velocityPxPerMs: perFrameToPerMs(sampledSpeed)
    };
  });
}

export function runRace({
  lanes,
  speedTier,
  finishDistancePx,
  onFrame,
  onFinish
}) {
  let animationFrameId = 0;
  let winnerLaneId = null;
  let previousTime = 0;

  const velocityByLane = new Map();
  const positionByLane = new Map();

  const sampled = assignLaneVelocities(lanes, speedTier);
  for (const row of sampled) {
    velocityByLane.set(row.laneId, row.velocityPxPerMs);
    positionByLane.set(row.laneId, 0);
  }

  const tick = (time) => {
    if (winnerLaneId !== null) {
      return;
    }

    if (!previousTime) {
      previousTime = time;
    }

    const dt = Math.max(0, time - previousTime);
    previousTime = time;

    for (const lane of lanes) {
      const laneId = lane.laneId;
      const velocity = velocityByLane.get(laneId) ?? 0;
      const current = positionByLane.get(laneId) ?? 0;
      const next = current + velocity * dt;
      const clamped = Math.min(next, finishDistancePx);
      positionByLane.set(laneId, clamped);

      if (winnerLaneId === null && clamped >= finishDistancePx) {
        winnerLaneId = laneId;
      }
    }

    const snapshot = lanes.map((lane) => ({
      laneId: lane.laneId,
      positionPx: positionByLane.get(lane.laneId) ?? 0
    }));

    onFrame(snapshot);

    if (winnerLaneId !== null) {
      onFinish(winnerLaneId, snapshot);
      return;
    }

    animationFrameId = requestAnimationFrame(tick);
  };

  animationFrameId = requestAnimationFrame(tick);

  return {
    stop() {
      cancelAnimationFrame(animationFrameId);
    },
    sampledVelocities: sampled
  };
}

export function updateSessionMetrics(state, elements) {
  elements.racesRun.textContent = String(state.metrics.sessionRacesRun);
}

import {
  ICON_OPTIONS,
  state,
  beginRace,
  finishRace,
  getPredictedWinnerLaneId,
  incrementSessionRaceCount,
  markReadyState,
  resetLanePositions,
  setError,
  setLaneIcon,
  setLaneName,
  setLanePosition,
  setLaneVelocity,
  setPredictedWinner,
  setResult,
  setSpeedTier,
  setTrackLength,
  setWarning
} from "./state.js";
import { validateBeforeStart } from "./validation.js";
import { runRace } from "./raceEngine.js";
import { updateSessionMetrics } from "./metrics.js";

const elements = {
  laneConfigList: document.querySelector("#lane-config-list"),
  track: document.querySelector("#track"),
  warningText: document.querySelector("#warning-text"),
  errorText: document.querySelector("#error-text"),
  resultText: document.querySelector("#result-text"),
  startButton: document.querySelector("#start-btn"),
  racesRun: document.querySelector("#races-run")
};

let activeRaceControl = null;

function iconById(iconId) {
  return ICON_OPTIONS.find((icon) => icon.id === iconId) ?? ICON_OPTIONS[0];
}

function renderLaneConfigControls() {
  elements.laneConfigList.innerHTML = "";

  for (const lane of state.lanes) {
    const card = document.createElement("section");
    card.className = "lane-config";

    const topRow = document.createElement("div");
    topRow.className = "lane-config-top";

    const laneLabel = document.createElement("strong");
    laneLabel.textContent = `Lane ${lane.laneId}`;
    topRow.appendChild(laneLabel);

    const iconList = document.createElement("div");
    iconList.className = "icon-options";

    for (const icon of ICON_OPTIONS) {
      const label = document.createElement("label");
      const input = document.createElement("input");
      input.type = "radio";
      input.name = `lane-${lane.laneId}-icon`;
      input.value = icon.id;
      input.checked = lane.selectedIconId === icon.id;
      input.addEventListener("change", () => {
        setLaneIcon(lane.laneId, icon.id);
        syncValidationMessages();
        renderTrackLanes();
      });

      const glyph = document.createElement("span");
      glyph.className = "icon";
      glyph.textContent = icon.symbol;

      label.append(input, glyph);
      iconList.appendChild(label);
    }

    topRow.appendChild(iconList);

    const nameInput = document.createElement("input");
    nameInput.className = "bug-name-input";
    nameInput.type = "text";
    nameInput.maxLength = 24;
    nameInput.value = lane.bugName;
    nameInput.placeholder = "Bug name";
    nameInput.addEventListener("input", (event) => {
      setLaneName(lane.laneId, event.target.value);
      syncValidationMessages();
      renderTrackLanes();
    });

    card.append(topRow, nameInput);
    elements.laneConfigList.appendChild(card);
  }
}

function renderTrackLanes() {
  elements.track.innerHTML = "";

  for (const lane of state.lanes) {
    const laneRow = document.createElement("div");
    laneRow.className = "track-lane";
    laneRow.dataset.laneId = String(lane.laneId);

    const predictCell = document.createElement("div");
    const predictInput = document.createElement("input");
    predictInput.type = "radio";
    predictInput.name = "predicted-winner";
    predictInput.checked = lane.predictedWinner;
    predictInput.disabled = state.race.status === "racing";
    predictInput.addEventListener("change", () => {
      setPredictedWinner(lane.laneId);
      syncValidationMessages();
      renderTrackLanes();
    });
    predictCell.appendChild(predictInput);

    const laneCell = document.createElement("div");
    laneCell.className = "lane-label";
    laneCell.textContent = `Lane ${lane.laneId}`;

    const runway = document.createElement("div");
    runway.className = "bug-runway";

    const bug = document.createElement("div");
    bug.className = "bug-runner";
    bug.dataset.role = "bug-runner";
    bug.dataset.laneId = String(lane.laneId);

    const icon = document.createElement("span");
    icon.className = "icon";
    icon.textContent = iconById(lane.selectedIconId).symbol;

    const name = document.createElement("span");
    name.className = "bug-name";
    name.textContent = lane.bugName.trim() || `Bug ${lane.laneId}`;

    bug.append(icon, name);
    bug.style.transform = `translate(${lane.positionPx}px, -50%)`;
    runway.appendChild(bug);

    laneRow.append(predictCell, laneCell, runway);
    elements.track.appendChild(laneRow);
  }

  const firstRunway = elements.track.querySelector(".bug-runway");
  const firstRunner = elements.track.querySelector(".bug-runner");
  if (firstRunway && firstRunner) {
    const finishDistancePx = Math.max(
      0,
      firstRunway.clientWidth - firstRunner.clientWidth - 4
    );
    setTrackLength(finishDistancePx);
  }
}

function syncValidationMessages() {
  const validation = validateBeforeStart(state.lanes);
  setWarning(validation.warning);

  if (validation.error && state.race.status !== "racing") {
    setError(validation.error);
  } else if (!validation.error) {
    setError("");
  }

  elements.warningText.textContent = state.ui.warning;
  elements.errorText.textContent = state.ui.error;
}

function paintLanePositions(snapshot) {
  for (const row of snapshot) {
    setLanePosition(row.laneId, row.positionPx);
    const runner = elements.track.querySelector(
      `.bug-runner[data-lane-id="${row.laneId}"]`
    );
    if (runner) {
      runner.style.transform = `translate(${row.positionPx}px, -50%)`;
    }
  }
}

function resetForNextRace() {
  resetLanePositions();
  markReadyState();
  renderTrackLanes();
}

function handleStartClick() {
  if (state.race.status === "racing") {
    return;
  }

  const validation = validateBeforeStart(state.lanes);
  setWarning(validation.warning);
  setError(validation.error);
  setResult("");
  elements.warningText.textContent = state.ui.warning;
  elements.errorText.textContent = state.ui.error;
  elements.resultText.textContent = "";

  if (!validation.valid) {
    return;
  }

  resetLanePositions();
  renderTrackLanes();
  beginRace();
  elements.startButton.disabled = true;

  activeRaceControl?.stop();

  activeRaceControl = runRace({
    lanes: state.lanes,
    speedTier: state.settings.speedTier,
    finishDistancePx: state.settings.trackLengthPx,
    onFrame(snapshot) {
      paintLanePositions(snapshot);
    },
    onFinish(winnerLaneId, snapshot) {
      paintLanePositions(snapshot);
      finishRace(winnerLaneId);
      incrementSessionRaceCount();
      updateSessionMetrics(state, elements);

      const predictedLane = getPredictedWinnerLaneId();
      const wasCorrect = predictedLane === winnerLaneId;
      const winnerLane = state.lanes.find((lane) => lane.laneId === winnerLaneId);
      const winnerName = winnerLane?.bugName.trim() || `Bug ${winnerLaneId}`;

      setResult(
        wasCorrect
          ? `Winner: ${winnerName} (Lane ${winnerLaneId}). You guessed correctly!`
          : `Winner: ${winnerName} (Lane ${winnerLaneId}). Better luck next race!`
      );
      elements.resultText.textContent = state.ui.result;

      elements.startButton.disabled = false;
      resetForNextRace();
      syncValidationMessages();
    }
  });

  for (const velocity of activeRaceControl.sampledVelocities) {
    setLaneVelocity(velocity.laneId, velocity.velocityPxPerFrame);
  }
}

function wireSpeedControls() {
  const radios = document.querySelectorAll('input[name="speed"]');
  for (const radio of radios) {
    radio.addEventListener("change", (event) => {
      setSpeedTier(event.target.value);
    });
  }
}

function init() {
  renderLaneConfigControls();
  renderTrackLanes();
  wireSpeedControls();
  updateSessionMetrics(state, elements);
  markReadyState();
  syncValidationMessages();

  elements.startButton.addEventListener("click", handleStartClick);

  window.addEventListener("resize", () => {
    renderTrackLanes();
  });
}

init();

